using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TransportHandoverTests
{
    static EntityId Id(string x)=>new(x);
    static TransportTerms Terms=>new(Id("job:transport"),Id("person:issuer"),Id("person:carrier"),Id("person:recipient"),Id("site:source"),Id("site:destination"),Id("person:issuer"),Id("lot:rice"),"rice","person-second",100,20,0,10,100);
    static HandoverInput Input(HandoverAction a,long rev,long at=1)=>new(Id("op:"+rev),a,a==HandoverAction.Cancel?Terms.Issuer:Terms.Carrier,a==HandoverAction.Deliver?Terms.Destination:Terms.Source,a==HandoverAction.Deliver?Terms.Recipient:a==HandoverAction.Cancel?Terms.Carrier:Terms.Issuer,a is HandoverAction.Collect or HandoverAction.Deliver or HandoverAction.Pay or HandoverAction.Return?Id("transfer:"+rev):null,at,rev);
    static TransportHandoverState Begin()=>TransportHandover.Offer(Terms);
    static TransportHandoverState To(int n){var s=Begin();var actions=new[]{HandoverAction.Accept,HandoverAction.Collect,HandoverAction.Deliver,HandoverAction.Report,HandoverAction.Pay};for(int j=0;j<n;j++)s=TransportHandover.Apply(s,Input(actions[j],j,j+1)).State;return s;}
    [Fact]public void CargoCustodyDoesNotConferOwnership(){var s=To(2);Assert.Equal(Terms.Carrier,TransportHandover.Validate(s).Holder);Assert.Equal(Terms.Issuer,s.Terms.Owner);s=To(3);Assert.Equal(Terms.Recipient,TransportHandover.Validate(s).Holder);Assert.Equal(Terms.Issuer,s.Terms.Owner);}
    [Fact]public void ReportCreatesDebtAndOnlyPaymentSettles(){Assert.Equal(0,TransportHandover.Validate(To(3)).FeeOwed);Assert.Equal(20,TransportHandover.Validate(To(4)).FeeOwed);Assert.Equal(0,TransportHandover.Validate(To(5)).FeeOwed);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ActualFileRestorePreservesJournalAndFuture(int n){var p=Path.Combine(Path.GetTempPath(),"transport-"+Guid.NewGuid()+".json");try{var s=To(n);File.WriteAllBytes(p,TransportHandover.Save(s));var restored=TransportHandover.Restore(File.ReadAllBytes(p));Assert.Equal(ContractJson.CanonicalHash(s),ContractJson.CanonicalHash(restored));var all=To(5).Entries.Skip(n).ToArray();foreach(var e in all){s=TransportHandover.Apply(s,e.Input).State;restored=TransportHandover.Apply(restored,e.Input).State;}Assert.Equal(ContractJson.CanonicalHash(s),ContractJson.CanonicalHash(restored));}finally{File.Delete(p);}}
    [Theory][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void RetryOldReceiptAfterRestoreCannotRepeatEffect(int n){var s=TransportHandover.Restore(TransportHandover.Save(To(n)));var result=TransportHandover.Apply(s,s.Entries[0].Input);Assert.True(result.Repeated);Assert.Same(s,result.State);Assert.Equal(n,result.State.Entries.Length);}
    [Fact]public void SameIdDifferentPayloadIsRejected(){var s=To(1);Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(s,s.Entries[0].Input with{At=2}));}
    [Theory][InlineData(HandoverAction.Collect)][InlineData(HandoverAction.Deliver)][InlineData(HandoverAction.Report)][InlineData(HandoverAction.Pay)][InlineData(HandoverAction.Return)]public void CannotSkipAcceptance(HandoverAction a){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(Begin(),Input(a,0)));}
    [Fact]public void StaleRevisionCannotTakeCargo(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(1),Input(HandoverAction.Collect,0)));}
    [Fact]public void WrongRecipientCannotReceive(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(2),Input(HandoverAction.Deliver,2,3) with{Counterparty=Terms.Issuer}));}
    [Fact]public void WrongSiteCannotReceive(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(2),Input(HandoverAction.Deliver,2,3) with{Site=Terms.Source}));}
    [Fact]public void MissingTransactionCannotProvePickup(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(1),Input(HandoverAction.Collect,1,2) with{Transaction=null}));}
    [Fact]public void SameStockTransactionCannotDeliverAgain(){var s=To(2);Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(s,Input(HandoverAction.Deliver,2,3) with{Transaction=s.Entries[1].Input.Transaction}));}
    [Fact]public void ExactDeliveryDeadlineIsAccepted(){Assert.Equal(HandoverPhase.Delivered,TransportHandover.Validate(TransportHandover.Apply(To(2),Input(HandoverAction.Deliver,2,100)).State).Phase);}
    [Fact]public void LateDeliveryMustReturnInsteadOfDeletingCargo(){var s=To(2);Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(s,Input(HandoverAction.Deliver,2,101)));s=TransportHandover.Apply(s,Input(HandoverAction.Return,2,101)).State;Assert.Equal(HandoverPhase.Returned,TransportHandover.Validate(s).Phase);Assert.Equal(Terms.Issuer,TransportHandover.Validate(s).Holder);}
    [Fact]public void CancelCarryingRequiresRealReturn(){var s=TransportHandover.Apply(To(2),Input(HandoverAction.Cancel,2,3)).State;Assert.Equal(HandoverPhase.ReturnRequired,TransportHandover.Validate(s).Phase);Assert.Equal(Terms.Carrier,TransportHandover.Validate(s).Holder);s=TransportHandover.Restore(TransportHandover.Save(s));s=TransportHandover.Apply(s,Input(HandoverAction.Return,3,4)).State;Assert.Equal(HandoverPhase.Returned,TransportHandover.Validate(s).Phase);Assert.Equal(0,TransportHandover.Validate(s).FeeOwed);}
    [Theory][InlineData(0)][InlineData(1)]public void CancelBeforeCollectionCreatesNoCargoOrDebt(int n){var s=TransportHandover.Apply(To(n),Input(HandoverAction.Cancel,n,n+1)).State;Assert.Equal(HandoverPhase.Cancelled,TransportHandover.Validate(s).Phase);Assert.Equal(Terms.Issuer,TransportHandover.Validate(s).Holder);}
    [Fact]public void CannotCancelDeliveredReceipt(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(3),Input(HandoverAction.Cancel,3,4)));}
    [Fact]public void ExpiredOfferIsNotAccepted(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(Begin(),Input(HandoverAction.Accept,0,11)));}
    [Fact]public void UnrelatedActorCannotAccept(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(Begin(),Input(HandoverAction.Accept,0) with{Actor=Terms.Recipient}));}
    [Fact]public void CorruptRevisionRejectedDuringRestore(){var s=To(2);s=s with{Entries=[s.Entries[0],s.Entries[1] with{Revision=9}]};Assert.Throws<InvalidDataException>(()=>TransportHandover.Restore(ContractJson.Write(s)));}
    [Fact]public void DuplicatedJournalRejectedDuringRestore(){var s=To(1);s=s with{Entries=[s.Entries[0],s.Entries[0]]};Assert.Throws<InvalidDataException>(()=>TransportHandover.Restore(ContractJson.Write(s)));}
    [Fact]public void ReversedTimeRejected(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(2),Input(HandoverAction.Deliver,2,1)));}
    [Fact]public void ChangedSchemaRejected(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Restore(ContractJson.Write(Begin() with{Schema=2})));}
    [Fact]public void NegativeGoodsAndFeeRejected(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Offer(Terms with{Amount=0}));Assert.Throws<InvalidDataException>(()=>TransportHandover.Offer(Terms with{Fee=-1}));}
    [Fact]public void ThirdPartyGoodsRequireSeparateAuthorization(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Offer(Terms with{Owner=Terms.Recipient}));}
    [Fact]public void WrongCounterpartyCannotBeInventedAtReport(){Assert.Throws<InvalidDataException>(()=>TransportHandover.Apply(To(3),Input(HandoverAction.Report,3,4) with{Counterparty=Terms.Recipient}));}
}
